-- D1-only transfer control. Apply explicitly after 001–007 to test/new D1 only.
CREATE TABLE d1_store_identity (id TEXT PRIMARY KEY CHECK(length(id)=32)) STRICT;
INSERT INTO d1_store_identity VALUES(lower(hex(randomblob(16))));
CREATE TABLE d1_project_authority (
 project_id TEXT PRIMARY KEY, project_key TEXT NOT NULL, transfer_id TEXT NOT NULL,
 generation INTEGER NOT NULL CHECK(generation>0), role TEXT NOT NULL CHECK(role IN ('source','target','return')),
 state TEXT NOT NULL CHECK(state IN ('blocked','writable')), ever_opened INTEGER NOT NULL CHECK(ever_opened IN (0,1)),
 bundle_hash TEXT, updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE d1_transfer_operations (
 id TEXT PRIMARY KEY,project_id TEXT NOT NULL UNIQUE,project_key TEXT NOT NULL,
 source_store_id TEXT NOT NULL,target_store_id TEXT NOT NULL,return_store_id TEXT,
 generation INTEGER NOT NULL CHECK(generation>0),
 phase TEXT NOT NULL CHECK(phase IN ('preparing','prepared','activating','active','aborting','aborted','recovering','returned')),
 activation_intent INTEGER NOT NULL CHECK(activation_intent IN (0,1)),created_at TEXT NOT NULL
) STRICT;
CREATE TABLE d1_transfer_imports (
 project_id TEXT PRIMARY KEY,transfer_id TEXT NOT NULL,bundle_hash TEXT NOT NULL,
 source_store_id TEXT NOT NULL,role TEXT NOT NULL,generation INTEGER NOT NULL
) STRICT;
CREATE TABLE d1_import_origins (
 project_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('event','link')),row_id TEXT NOT NULL,
 PRIMARY KEY(project_id,kind,row_id)
) STRICT;
CREATE TABLE d1_write_guard (id INTEGER PRIMARY KEY CHECK(id=1),ok INTEGER NOT NULL CONSTRAINT skilly_generation_allowed CHECK(ok=1)) STRICT;
CREATE TABLE d1_transfer_guard (id INTEGER PRIMARY KEY CHECK(id=1),ok INTEGER NOT NULL CONSTRAINT skilly_transfer_change CHECK(ok=1)) STRICT;
CREATE TRIGGER d1_fence_projects_insert BEFORE INSERT ON projects WHEN EXISTS(SELECT 1 FROM d1_project_authority a WHERE a.state='blocked' AND ((a.project_id=NEW.id OR a.project_key=NEW.project_key))) BEGIN SELECT RAISE(ABORT,'project_write_blocked'); END;
CREATE TRIGGER d1_fence_projects_update BEFORE UPDATE ON projects WHEN EXISTS(SELECT 1 FROM d1_project_authority a WHERE a.state='blocked' AND ((a.project_id=OLD.id OR a.project_key=OLD.project_key) OR (a.project_id=NEW.id OR a.project_key=NEW.project_key))) BEGIN SELECT RAISE(ABORT,'project_write_blocked'); END;
CREATE TRIGGER d1_fence_projects_delete BEFORE DELETE ON projects WHEN EXISTS(SELECT 1 FROM d1_project_authority a WHERE a.state='blocked' AND ((a.project_id=OLD.id OR a.project_key=OLD.project_key))) BEGIN SELECT RAISE(ABORT,'project_write_blocked'); END;
